{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

const _pageSize = 20;

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;
  late final ScrollController _scrollController;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;
  bool _isInitialLoading = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadInitialPage();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  Future<void> _loadInitialPage() async {
    final currencyRepository = context.read<CurrencyRepository>();
    _currentPage = 0;
    _hasMore = true;
    _allCurrencies.clear();
    _filteredCurrenciesNotifier.value = [];

    final page = await currencyRepository.fetchRates(
      const CurrencyPageRequest(base: 'USD', page: 0, pageSize: _pageSize),
    );
    _onPageLoaded(page);
    return;
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;
    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = _currentPage + 1;
    final page = await currencyRepository.fetchRates(
      CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: _pageSize),
    );

    if (!mounted) return;
    setState(() {
      _isLoadingMore = false;
      _hasMore = page.hasMore;
      _currentPage = page.page;
      _allCurrencies.addAll(page.items);
      currencyRepository.saveCurrencyList(_allCurrencies);
    });
  }

  void _onPageLoaded(CurrencyPage page) {
    setState(() {
      _isInitialLoading = false;
      _hasMore = page.hasMore;
      _currentPage = page.page;
      _allCurrencies = List<CurrencyModel>.from(page.items);
      currencyRepository.saveCurrencyList(_allCurrencies);
    });

    _fadeController.forward();
  }

  CurrencyRepository get currencyRepository => context.read<CurrencyRepository>();

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _loadInitialPage();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
    _scrollController = ScrollController();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: _isInitialLoading
          ? const Center(child: CircularProgressIndicator())
          : FadeTransition(
              opacity: _fadeController.view,
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                    child: SearchView(onChanged: _filterCurrencies),
                  ),
                  Expanded(
                    child: ValueListenableBuilder<List<CurrencyModel>>(
                      valueListenable: _filteredCurrenciesNotifier,
                      builder: (context, data, _) {
                        return ListView.builder(
                          controller: _scrollController,
                          itemCount: data.length + (_isLoadingMore ? 1 : 0),
                          itemBuilder: (context, index) {
                            if (index >= data.length) {
                              return const Center(child: Padding(padding: EdgeInsets.all(8), child: CircularProgressIndicator()));
                            }
                            final currency = data[index];
                            return Padding(
                              key: ValueKey(currency.id),
                              padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                              child: CurrencyCard(model: currency),
                            );
                          },
                          padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
      bottomNavigationBar: _hasMore
          ? Padding(
              padding: const EdgeInsets.all(16),
              child: ElevatedButton(
                onPressed: _isLoadingMore || !_hasMore ? null : _loadNextPage,
                child: _isLoadingMore
                    ? const SizedBox(
                        width: 24,
                        height: 24,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : Text(context.loc.showMore),
              ),
            )
          : null,
    );
  }
}
